// Exercise 8.1. Write a function that takes and returns an istream&.

#include <iostream>
#include <string>

std::istream& printInput(std::istream &is)
{
    std::string line;
    while (getline(is, line))
        std::cout << line << '\n';
    is.clear();
    return is;
}

