// Exercise 8.10. Write a program to store each line from a file in a vector<string>. Now use an istringstream to read each element from the vector a word at a time.

#include <iostream>
#include <fstream>
#include <sstream>
#include <string>
#include <vector>

std::vector<std::string> loadFile(const std::string &file)
{
    std::ifstream input(file);
    if (!input) {
        std::cerr << "counldn't open: " + file << '\n';
        exit(EXIT_FAILURE); // C-style exit
    }
    std::vector<std::string> data;
    std::string line;
    while (getline(input, line))
        data.push_back(line);
    return data;
}

int main(int argc, char **argv)
{
    if (--argc != 1) {
        std::cerr << "Usage: " + std::string(*argv) + " <filename>\n";
        return -1;
    }
    auto p = argv + 1;
    std::vector<std::string> file = loadFile(*p);
    for (const auto &line : file) {
        std::istringstream ss(line);
        std::string word;
        while (ss >> word)
            std::cout << word << '\n';
    }
    return 0;
}

8.11.text:
/*
 * Answer: first, declare the unbound stream record outside the outer loop,
 * than copy the string line into the stream at every iteration of the otter
 * loop, and, finally, clear the stream just before looping back so it will be
 * in a valid state on the next line copy.
 */

#include <iostream>
#include <sstream>
#include <string>
#include <vector>

struct PersonInfo {
    std::string name;
    std::vector<std::string> phones;
};

std::ostream& print(std::ostream &os, const PersonInfo &person)
{
    os << person.name;
    for (const auto &number : person.phones)
        std::cout << ' ' << number;
    return os;
}

int main()
{
    std::string line, word;
    std::vector<PersonInfo> people;
    std::istringstream record; // unbound istringstream
    while (getline(std::cin, line)) {
        PersonInfo info;
        record.str(line); // copy line to stream
        record >> info.name;
        while (record >> word)
            info.phones.push_back(word);
        people.push_back(info);
        record.clear(); // rest stream back to valid state
    }
    for (const auto &person : people) // print vector
        print(std::cout, person) << '\n';
    return 0;
}

